class ColorConvertTest(unittest.TestCase):
    def close(self, got, expected, label):
        self.assertEqual(len(got), len(expected), label)
        for x, y in zip(got, expected):
            self.assertAlmostEqual(x, y, delta=1e-6, msg=label)

    def test_hex(self):
        for text, rgba, canonical in HEX:
            self.close(parse_hex(text), rgba, text)
            self.assertEqual(to_hex(*parse_hex(text)), canonical)
        for text in HEX_INVALID:
            with self.assertRaises(ValueError):
                parse_hex(text)
        for channels, expected in TO_HEX:
            self.assertEqual(to_hex(*channels), expected)

    def test_hsl_and_oklch(self):
        for text, expected in HSL:
            self.close(rgb_to_hsl(*parse_hex(text)[:3]), expected, text)
        for hsl, expected in HSL_TO_RGB:
            self.close(hsl_to_rgb(*hsl), expected, hsl)
        for text, expected in OKLCH:
            self.close(rgb_to_oklch(*parse_hex(text)[:3]), expected, text)
        for lch, expected in OKLCH_TO_RGB:
            self.close(oklch_to_rgb(*lch), expected, lch)
        for rgb, expected in IN_GAMUT:
            self.assertEqual(in_gamut(*rgb), expected)


if __name__ == "__main__":
    unittest.main()
